  "def generate_answers(prompt, pred_answer, num_answers=10):",
  "    \"\"\"Generates N alternative answers for a given prompt to measure consistency.\"\"\"",
  "",
  "    sys_msg = (",
  "        \"You are a helpful QA assistant. Answer concisely and factually.\"",
  "        \" When asked multiple times, use slightly different wording each time while keeping\"",
  "        \" the meaning and final answer consistent.\"",
  "    )",
  "    ",
  "    messages = [",
  "        {\"role\": \"system\", \"content\": sys_msg},",
  "        {\"role\": \"user\", \"content\": prompt},",
  "    ]",
  "",
  "    main_output = _clean_generated_text(pred_answer)",
  "",
  "    alternatives = []",
  "    for _ in range(num_answers - 1):",
  "        alt_output = vertex_generate(",
  "            messages,",
  "            temperature=0.9,",
  "            top_p=0.9,",
  "            max_tokens=MAX_TOKENS_ANSWER,",
  "            thinking_budget=0,",
  "        )",
  "        alternatives.append(_clean_generated_text(alt_output))",
  "",
  "    return main_output, alternatives",
