  "def expand_short_answer(question: str, answer: str) -> str:",
  "    \"\"\"Expands very short answers into full sentences to improve the processing accuracy of the NLI model.\"\"\"",
  "",
  "    ans = _clean_generated_text(answer)",
  "    ",
  "    if len(ans.split()) >= 6:",
  "        return ans",
  "        ",
  "    ans_clean = ans.rstrip(\".:;!? \")",
  "    q_clean = question.replace(\"?\", \"\").replace(\"\\n\", \" \").strip()",
  "    q_clean = re.sub(r'[.!;:…]+$', '', q_clean)",
  "    q_clean = q_clean.replace(\"'\", '\"')",
  "    ",
  "    return f\"The answer is {ans_clean}.\"",
  "",
  "def _clean_generated_text(text: str) -> str:",
  "    \"\"\"Removes markdown formatting artifacts and normalizes whitespace from the generated text.\"\"\"",
  "",
  "    text = (text or \"\").strip()",
  "",
  "    text = re.sub(r\"(\\*\\*|__|\\*|`)\", \"\", text)",
  "    text = re.sub(r\"^[>\\-\\#]+\\s*\", \"\", text, flags=re.MULTILINE)",
  "",
  "    text = re.sub(r\"[ \\t]+\", \" \", text)",
  "    text = re.sub(r\"\\n\\s+\", \"\\n\", text)",
  "    return text.strip()",
