  "            #step 3: expand the short answer, clean duplicate and check relevance of the facts",
  "            #short answers are poorly processed by NLI model, so we expand it with \"The answer is\" to avoid this issue",
  "            main_ans = expand_short_answer(prompt, main_ans)",
  "            alternatives = [expand_short_answer(prompt, alt) for alt in alternatives]",
  "",
  "            #sentences segmentation of the main facts to evaluate with granularity the confidence in each sentence",
  "            original_sentences = nltk.sent_tokenize(main_ans)",
