  "                all_facts = []",
  "                for sent in nltk.sent_tokenize(alt):",
  "                    all_facts.extend(extract_facts_from_sentence(sent))",
  "                facts_per_alternative.append(deduplicate_facts(all_facts, prompt))",
  "",
  "            sentence_scores = []",
