  "                    gold_scores_per_sentence.append([None] * len(facts))",
  "                    continue",
  "",
  "                # evaluate local atomic facts against the gold answer using LLM (for information as it performs poorer than Prometheus Score)",
  "                #check whether the extracted facts from main answer support the gold answer",
