  "                gold_scores_per_sentence=gold_scores_per_sentence,",
  "                prometheus_score=prom_score,",
  "            )",
  "",
  "            valid_nli = [s for s in sentence_scores if s is not None]",
  "            valid_gold_lists = [g for g in gold_scores_per_sentence if g is not None]",
  "            flat_gold = [val for sublist in valid_gold_lists for val in sublist if val is not None]",
  "",
  "            total_relevant_facts = sum(sum(r) for r in relevance_per_sentence if r)",
  "",
  "            if total_relevant_facts == 0:",
