  "                overall_llm_gold = 0.0",
  "                overall_nli_gold = 0.0",
  "            else:",
  "                overall_entropy = np.mean(valid_nli) if valid_nli else None",
  "                overall_llm_gold = max(flat_gold) if flat_gold else None",
  "                overall_nli_gold = np.mean(all_nli_gold_scores) if all_nli_gold_scores else None",
  "",
  "            record_summary[\"nli_score\"] = overall_entropy",
  "            record_summary[\"gold_score\"] = overall_llm_gold",
  "            record_summary[\"nli_gold\"] = overall_nli_gold",
  "            record_summary[\"facts_count\"] = total_relevant_facts",
  "            record_summary[\"sentence_raw_matrix\"] = sentence_raw_matrix",
