  "            record_summary[\"bypass_reason\"] = f\"({type(e).__name__})\"",
  "        ",
  "        record_summary[\"time\"] = time.time() - start_time",
  "        record_summary[\"tokens\"] = _prompt_tokens",
  "        summary_data.append(record_summary)",
  "",
  "        print(f\"  Tokens: {record_summary['tokens']} | Time: {record_summary['time']:.2f}s -> {out_html}\\n\")",
  "    ",
  "    #calculate the optimal thresholds and produce the summary HTML file",
  "    optimal_thresholds, summary_data, plot_filename = optimize_and_update_thresholds(summary_data, output_dir)",
