  "    prom_vals = []",
  "    for row in summary_data:",
  "        n = row.get(\"nli_score\")",
  "        p = row.get(\"prometheus_score\")",
  "        if n is not None and p is not None and p > 0:",
  "            nli_vals.append(n)",
  "            prom_vals.append(p)",
  "            ",
  "    spearman_corr = None",
  "    pearson_corr = None",
  "",
  "    if len(nli_vals) > 1:",
  "        sp = spearmanr(nli_vals, prom_vals)",
  "        spearman_corr = float(sp.correlation if hasattr(sp, \"correlation\") else sp[0])",
  "        pearson_corr = float(np.corrcoef(nli_vals, prom_vals)[0, 1])",
  "",
  "    #produce the summary HTML file",
  "    summary_path = os.path.join(output_dir, \"execution_summary.html\")",
  "    write_summary_html(summary_data, summary_path, optimal_thresholds, plot_filename, spearman_corr, pearson_corr)",
